from pathlib import Path
import json,math,hashlib,zipfile,shutil,html
R=Path(__file__).resolve().parents[2]; O=R/'output/900mm-layout-current'; V=O/'ci-verified'; D=R/'docs/wing-panel-stress-analyzer/validation'
J=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda b:hashlib.sha256(b).hexdigest()
a=J(V/'wing-matched-layouts/layout-results.json')
rows=[x for x in a['results'] if x['speed']==15 and x['elements']==40 and x['variant'] in ['spar5','spar0','rod-bonded','rod-sleeve']]
names={'spar5':'Two spars + five ribs','spar0':'Two spars, no ribs','rod-bonded':'Two bonded rods','rod-sleeve':'Two rods in sliding sleeves','foam-rods':'Solid EPS + two bonded rods','foam-spars':'Solid EPS + two bonded spars'}
coupled={}
summary={'physicsCommit':'99968453ad8e17754a45dcb54d418e13388e2160','workflow':'https://github.com/Ehsan-Roohi/Aerospace-Structures/actions/runs/42402193083','qualification':'Independent numerical and analytical verification; no experiment or ANSYS comparison.','semiSpan_mm':900,'chord_mm':400,'speed_m_s':15,'alpha_deg':0,'selfWeight':False,'hollow':[],'foam':[]}
for r in rows:summary['hollow'].append({k:r[k] for k in ['variant','tip','twistDeg','mass','admission','verification']})
for name,index in [('foam-rods',2),('foam-spars',3)]:
 c=J(V/f'wing-coupled-{index}'/f'coupled-{name}-15.json'); coupled[name]=c
 assert c['admitted'] and c['converged'] and c['version']=='finite-rotation-coupled-2'
 assert c['foamModel']['transverseShearIncluded'] and all(x['passed'] for x in c['admission']['checks'])
 t=c['profile'][-1]; lift=2*c['rootForce'][2]
 summary['foam'].append({'variant':name,'mass_g':c['massG'],'tip_mm':t['displacement'][2],'incidence_deg':math.degrees(t['elasticIncidence']),'liftFullWing_N':lift,'CL':lift/(.5*1.225*225*.72),'passedChecks':len(c['admission']['checks']),'teachingTipLimit_mm':45,'meetsTeachingTipLimit':abs(t['displacement'][2])<=45,'foamModel':c['foamModel']})
def table(head,body):
 return '<div class="scroll"><table><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in body)+'</table></div>'
hollow=table(['Construction','Semi-wing mass (g)','Tip z (mm)','Twist (deg)'],[[names[r['variant']],f'{r["mass"]["total"]:.1f}',f'{r["tip"]:.4f}',f'{r["twistDeg"]:.5f}'] for r in rows])
foam=table(['Construction','Semi-wing mass (g)','Tip z (mm)','Incidence (deg)','Full lift (N)','CL'],[[names[r['variant']],f'{r["mass_g"]:.1f}',f'{r["tip_mm"]:.3f}',f'{r["incidence_deg"]:.4f}',f'{r["liftFullWing_N"]:.3f}',f'{r["CL"]:.4f}'] for r in summary['foam']])
svg=['<svg viewBox="0 0 720 340" role="img" aria-label="Accepted foam displacement profiles">']
X=lambda y:65+y/900*630
Y=lambda z:285-z/65*260
for z in [0,10,20,30,40,50,60]:svg.append(f'<path d="M65 {Y(z)}H695" stroke="#ddd"/><text x="55" y="{Y(z)+4}" text-anchor="end">{z}</text>')
for y in [0,150,300,450,600,750,900]:svg.append(f'<text x="{X(y)}" y="309" text-anchor="middle">{y}</text>')
svg.append('<path d="M65 25V285H695" fill="none" stroke="#333"/><text x="370" y="335" text-anchor="middle">Span position (mm)</text><text transform="translate(18,170) rotate(-90)" text-anchor="middle">Vertical displacement (mm)</text>')
for i,(name,c) in enumerate(coupled.items()):
 color=['#0067b1','#b54808'][i]; pts=' '.join(f'{X(t["y"]):.3f},{Y(t["displacement"][2]):.3f}' for t in c['profile'])
 svg.append(f'<polyline points="{pts}" fill="none" stroke="{color}" stroke-width="2.5"/><text x="90" y="{42+24*i}" fill="{color}">{html.escape(names[name])}</text>')
svg.append('</svg>')
report='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>900 mm wing comparison</title><style>body{max-width:1000px;margin:32px auto;padding:0 20px;font:17px/1.55 system-ui;color:#152334}h1{line-height:1.2}h2{margin-top:2em}.note{padding:16px;background:#eef5fa;border-left:4px solid #1266a0}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:10px;border-bottom:1px solid #ccd5df;text-align:right}td:first-child,th:first-child{text-align:left}svg{width:100%;font:14px system-ui}a{color:#005b9b}img{max-width:390px;width:100%}</style><body><h1>900 mm semi-span wing comparison</h1><p class="note">Release 0.5.0: independent numerical and analytical verification succeeded. This is not experimental validation, an ANSYS comparison, or flight/strength approval.</p><p>Each semi-span is 900 mm (full span 1800 mm). Imported Clark Y coordinates, constant chord 400 mm, zero sweep/dihedral, fully clamped roots. Speed 15 m/s, angle of attack zero, density 1.225 kg/m3. Self-weight off for matched pressure comparisons. All materials are illustrative.</p><h2>Hollow printed wing: fixed rigid-wing pressure</h2>'''+hollow+'''<p>PLA E 2000 MPa, density 1240 kg/m3, skin 1.2 mm. Two full-length I-spars at x/c 0.25 and 0.65: cap width 12 mm, cap/web thickness 1.2 mm. Five ribs are 1.6 mm thick at 150, 300, 450, 600 and 750 mm. Carbon rods are 4 mm diameter, E 25000 MPa and G 3000 MPa, at the same chord positions. Printed sleeves have 0.25 mm radial clearance. All four cases pass the one-way coupling screen at 15 m/s.</p><p><strong>Equal spar-case deflection does not mean ribs are unnecessary.</strong> This global beam includes rib mass but no diaphragm stiffness, section distortion or local skin buckling. With self-weight off, the additional 112.16 g of ribs does not change the global pressure bending. Local rib/skin assessment requires a shell/solid model or a physical test.</p><h2>Solid foam with internal reinforcement: full two-way solution</h2>'''+foam+''.join(svg)+'''<p>These are converged finite-rotation Reissner solutions with pressure recomputed on the deformed wing and transverse shear included. They differ from the fixed-pressure calculation above. Solid EPS: E 6 MPa, nu 0.10, density 20 kg/m3. No fabric or printed skin. Inserts are perfectly bonded and replace displaced foam volume; dimensions match the rods/spars above. Both cases pass all 18 numerical admission checks. The one-percent strain screen is a model-range screen, not measured foam strength.</p><p>The foam+spars case failed the former omitted-shear estimate (1.596% against 1%). The limit was retained and transverse shear was added to the model. Included-shear compliance refinement is 0.2970% for foam+rods and 0.0583% for foam+spars. Twist reduces lift relative to the rigid-wing value.</p><p><strong>Numerical admission is separate from a deflection requirement.</strong> The import cases set an illustrative tip limit of 45 mm (5% of 900 mm), not a universal aircraft allowable. Foam+rods bends 58.706 mm and therefore fails that chosen design limit even though its nonlinear solution is numerically admitted. Foam+spars at 10.020 mm passes that deflection limit. The five-percent small-displacement screen is also 45 mm here, but the finite-rotation solver can solve beyond that screen; it does not waive a design requirement. A flight-specific deflection limit still needs a design basis.</p><h2>Aerodynamics and the 50 m/s warning</h2><p>The common rigid-wing Fine eight-mesh pressure sequence gives CL 0.255562, Cm about quarter MAC -0.076978, CDi 0.004786 and CL/CDi 53.4. Full-wing lift at 15 m/s is 25.358 N. Pressure drag 0.004773 is another estimate of the same induced drag: do not add them. Viscous/profile drag and stall are not computed. One common pressure solution is reused because the outer geometry is identical.</p><p>All four hollow configurations fail the one-way coupling screen at 50 m/s. This warns that rigid-wing pressure is inconsistent with the flexible shape; it is not a universal span/speed limit or material failure. The two-spar/five-rib wing was additionally solved with full two-way finite rotations at 50 m/s: tip z 13.8105 mm, incidence -0.35449 degrees, full lift 265.552 N, all 16 numerical checks passed. No aircraft weight or trim target was supplied; these are load cases, not verified flight conditions.</p><h2>Independent checks</h2><ul><li>Force, moment and energy balance, plus printed-sleeve contact/slip checks.</li><li>Bonded-rod torsional locking repaired and checked against an independent analytical noncoaxial torsion solution; global 40/80-element refinement separately checked.</li><li>Section mass and unsymmetric bending against independent integrals; composite-circle torsion error 0.0803%.</li><li>Reissner shear against exact Timoshenko tip/uniform-load solutions, coupled shear, energy and coordinate objectivity; large finite rotation against independent planar first-integral quadrature.</li><li>Coupled pressure uncertainty, beam integration and independent section/axis refinement, with original criteria retained.</li></ul><p><a href="https://github.com/Ehsan-Roohi/Aerospace-Structures/actions/runs/42402193083">Verified physics CI: seven successful jobs</a>. <a href="900MM_LAYOUT_REVIEW.json">Machine-readable review</a>. Raw accepted solutions and SHA256 provenance are included in the kit.</p><h2>Ready-to-import cases</h2><p><a href="900mm-validation-kit.zip" download>Download validation kit</a>. All six native JSON files round-trip through the project importer. They contain the matched rigid-wing pressure at 15 m/s; this is not a saved converged flexible result. Use <strong>Flexible-wing results</strong> for the shear-inclusive coupled foam calculation.</p><ul>'''+''.join(f'<li><a href="cases/900mm-{v}.json" download>{html.escape(names[v])}</a></li>' for v in names)+'''</ul><p>Actual browser import of the foam+spars case was checked. This screenshot shows imported inputs, not a solved displacement field.</p><img src="foam-import-ui.jpg" alt="Imported solid EPS settings"><h2>Remaining limits</h2><p>Foam support currently requires a straight constant-chord single body and full-length perfectly bonded rods or spars. Foam crushing, debonding, sliding foam-channel contact and fabric skins are not validated. The section shear law uses the Poisson-zero approximation. No local skin/rib buckling, section distortion, material nonlinearity, divergence, flutter or experimental validation is claimed. ANSYS comparison requires matched geometry, material laws, connections, boundary conditions and geometric-nonlinearity settings.</p></body></html>'''
D.mkdir(exist_ok=True); (D/'900mm-layout-report.html').write_text(report,encoding='utf8'); (D/'900MM_LAYOUT_REVIEW.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf8')
cases=D/'cases'; cases.mkdir(exist_ok=True)
for p in sorted((O/'import-cases').glob('900mm-*.json')):shutil.copy2(p,cases/p.name)
assert len(list(cases.glob('900mm-*.json')))==6
shutil.copy2(O/'foam-import-ui.jpg',D/'foam-import-ui.jpg')
payload={str(p.relative_to(D)).replace('\\','/'):p.read_bytes() for p in [D/'900mm-layout-report.html',D/'900MM_LAYOUT_REVIEW.json',D/'foam-import-ui.jpg',*sorted(cases.glob('900mm-*.json'))]}
for p in sorted(V.rglob('*.json')):payload['raw/'+str(p.relative_to(V)).replace('\\','/')]=p.read_bytes()
manifest={'physicsCommit':summary['physicsCommit'],'workflow':summary['workflow'],'files':{n:{'bytes':len(b),'sha256':sha(b)} for n,b in payload.items()}}
payload['SHA256-MANIFEST.json']=(json.dumps(manifest,indent=2)+'\n').encode()
kit=D/'900mm-validation-kit.zip'
with zipfile.ZipFile(kit,'w',zipfile.ZIP_DEFLATED) as z:
 for name,b in payload.items():z.writestr(name,b)
with zipfile.ZipFile(kit) as z:
 for n,r in manifest['files'].items():assert sha(z.read(n))==r['sha256']
receipt={'kit':str(kit.relative_to(R)),'bytes':kit.stat().st_size,'sha256':sha(kit.read_bytes()),'entriesVerified':len(manifest['files'])}
(O/'delivery-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n'); print(json.dumps(receipt,indent=2))
